package vn.edu.vhu.ltdd.a5intent;
import android.content.Intent; import android.os.Bundle; import android.util.Log; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import androidx.core.content.IntentCompat;
public class DetailActivity extends AppCompatActivity {private static final String TAG="A5_241A010591";private Contact contact;private EditText edt;
@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_detail);Log.d(TAG,"Detail.onCreate");TextView info=findViewById(R.id.tvThongTin),sender=findViewById(R.id.tvNguoiGui);edt=findViewById(R.id.edtHoTenMoi);contact=IntentCompat.getParcelableExtra(getIntent(),MainActivity.EXTRA_CONTACT,Contact.class);String n=getIntent().getStringExtra(MainActivity.EXTRA_NGUOI_GUI);if(contact==null){info.setText(R.string.no_data);return;}info.setText(getString(R.string.detail_format,contact.getHoTen(),contact.getDienThoai(),contact.getEmail()));sender.setText(getString(R.string.sent_by,n));edt.setText(contact.getHoTen());findViewById(R.id.btnLuu).setOnClickListener(v->luu());findViewById(R.id.btnHuy).setOnClickListener(v->{setResult(RESULT_CANCELED);finish();});}
private void luu(){String h=edt.getText().toString().trim();if(h.isEmpty()){edt.setError(getString(R.string.err_empty));return;}contact.setHoTen(h);Intent k=new Intent();k.putExtra(MainActivity.EXTRA_CONTACT,contact);setResult(RESULT_OK,k);Log.d(TAG,"Trả kết quả: "+h);finish();}
@Override protected void onStart(){super.onStart();Log.d(TAG,"Detail.onStart");}@Override protected void onResume(){super.onResume();Log.d(TAG,"Detail.onResume");}@Override protected void onPause(){Log.d(TAG,"Detail.onPause");super.onPause();}@Override protected void onStop(){Log.d(TAG,"Detail.onStop");super.onStop();}@Override protected void onRestart(){super.onRestart();Log.d(TAG,"Detail.onRestart");}@Override protected void onDestroy(){Log.d(TAG,"Detail.onDestroy");super.onDestroy();}
}
